// Official 5.11 filterHeadParts, including its VIP-dependent removal branch.
import org.audiveris.omr.sheet.Book;
import java.util.*;import java.nio.file.*;import java.awt.*;
public class StemChunkHeadFilterProbe extends StemChunkRegistrationProbe {
 private final Object originalBook;
 public StemChunkHeadFilterProbe(Book b,SortedSet<Integer> ids){super(b,ids);originalBook=b;}
 static Object register(Object index,Object g,IdentityHashMap<Object,Integer> tags,java.util.List<Object>held)throws Exception {Object c=call(index,"registerOriginal",g);if(!tags.containsKey(c)){tags.put(c,tags.size()+1);held.add(c);}return c;}
 static Object sparse(int x,int y,int outside,int offset)throws Exception {int height=offset+outside;byte[]p=new byte[height];Arrays.fill(p,(byte)255);p[0]=0;for(int i=offset;i<height;i++)p[i]=0;return Class.forName("org.audiveris.omr.glyph.Glyph").getConstructor(int.class,int.class,Class.forName("org.audiveris.omr.run.RunTable")).newInstance(x,y,table(p,1,height,"VERTICAL"));}
 static String observe(Object sb,Object head,Object headGlyph,java.util.List<Object>parts,boolean vip,String mode,IdentityHashMap<Object,Integer>tags)throws Exception {
  call(head,"setVip",vip);Rectangle hb=(Rectangle)call(headGlyph,"getBounds");java.util.List<String>remaining=new ArrayList<>();
  for(Object g:parts){Rectangle b=(Rectangle)call(g,"getBounds");int overlap=(Integer)Class.forName("org.audiveris.omr.math.GeoUtil").getMethod("yOverlap",Rectangle.class,Rectangle.class).invoke(null,hb,b);if(overlap<=0){remaining.add("null");continue;}Object points=call(g,"getPointsCollector");int[]xs=(int[])call(points,"getXValues"),ys=(int[])call(points,"getYValues");int contained=0;for(int i=0;i<ys.length;i++)if(ys[i]>=hb.y&&ys[i]<=hb.y+hb.height-1&&(Boolean)headGlyph.getClass().getMethod("contains",Point.class).invoke(headGlyph,new Point(xs[i],ys[i])))contained++;remaining.add(""+((Integer)call(g,"getWeight")-contained));}
  java.util.List<Object>kept=new ArrayList<>(parts);call(sb,"filterHeadParts",kept);
  return "{\"mode\":\""+mode+"\",\"vip\":"+vip+",\"part_ids\":"+tokens(parts,tags)+",\"remaining_weights\":["+String.join(",",remaining)+"],\"retained_ids\":"+tokens(kept,tags)+"}";
 }
 public void process(){try{
  Object sheet=call(((java.util.List<?>)call(originalBook,"getStubs")).get(0),"getSheet"),sys=((java.util.List<?>)call(sheet,"getSystems")).get(0);Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");
  java.util.List<String>groups=new ArrayList<>();int count=0;
  for(Object head:(java.util.List<?>)get(retr,"systemHeads")){Object linker=call(head,"getLinker");if(linker==null)continue;boolean oldVip=(Boolean)call(head,"isVip");Object hg=call(head,"getGlyph");Rectangle hb=(Rectangle)call(hg,"getBounds");Object pts=call(hg,"getPointsCollector");int[]xs=(int[])call(pts,"getXValues"),ys=(int[])call(pts,"getYValues");int pick=-1;for(int i=0;i<ys.length;i++)if(ys[i]<hb.y+hb.height-1){pick=i;break;}if(pick<0)throw new IllegalStateException("no positive-y-overlap control pixel");
   for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object corner=call(linker,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert)),sb=get(corner,"sb");if(sb==null)continue;count++;Object index=Class.forName("org.audiveris.omr.glyph.GlyphIndex").getConstructor().newInstance();call(index,"initTransients",sheet);IdentityHashMap<Object,Integer>tags=new IdentityHashMap<>();java.util.List<Object>held=new ArrayList<>(),actual=new ArrayList<>(),synthetic=new ArrayList<>();for(Object g:raw(sb,sys))actual.add(register(index,g,tags,held));for(int outside:new int[]{14,15,16})synthetic.add(register(index,sparse(xs[pick],ys[pick],outside,hb.height+10),tags,held));Object edge=register(index,glyph(xs[pick],hb.y+hb.height-1,1,1,"VERTICAL"),tags,held);Object zero=register(index,glyph(xs[pick],hb.y+hb.height,1,1,"VERTICAL"),tags,held);
    java.util.List<String>rows=new ArrayList<>();try{rows.add(observe(sb,head,hg,actual,oldVip,"actual",tags));for(boolean vip:new boolean[]{false,true})for(int i=0;i<3;i++)rows.add(observe(sb,head,hg,Collections.singletonList(synthetic.get(i)),vip,"remaining-"+(14+i),tags));rows.add(observe(sb,head,hg,Arrays.asList(synthetic.get(0),synthetic.get(0)),true,"duplicate-remaining14",tags));rows.add(observe(sb,head,hg,Collections.singletonList(edge),true,"last-head-row",tags));rows.add(observe(sb,head,hg,Collections.singletonList(zero),true,"zero-y-overlap",tags));rows.add(observe(sb,head,hg,Collections.emptyList(),true,"empty",tags));}finally{call(head,"setVip",oldVip);}
    java.util.List<String>catalog=new ArrayList<>();for(Object g:held)catalog.add("{\"id\":"+tags.get(g)+",\"glyph\":"+physical(g)+"}");groups.add("{\"head_glyph\":"+physical(hg)+",\"catalog\":["+String.join(",",catalog)+"],\"cases\":["+String.join(",",rows)+"]}");
   }
  }
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"JVM_ids_normalized_to_canonical_identity_tokens\":true,\"scope\":\"Actual Head CLinker chunk pixel filter with original VIP condition, 14/15/16 threshold and zero-y-overlap; no full lookupChunks/cache/SIG/page claim\",\"builders\":"+count+",\"groups\":["+String.join(",",groups)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
